# owner: platform
"""Seat students in rows for a printed chart."""

from typing import List, Tuple

from rosterkit.models import Student

def name_order(student: Student) -> Tuple[str, str]:
    """Last name first, then first name, ignoring case."""
    names = (student.last_name, student.first_name)
    return tuple(name.casefold() for name in names)

def seating_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """One line of text per row, sorted by last name."""
    if seats_per_row <= 0:
        raise ValueError(
            f"seats must be positive: {seats_per_row}"
        )
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(students, key=name_order)
    rows = []
    for start in range(0, len(ordered), seats_per_row):
        seated = ordered[start : start + seats_per_row]
        number = start // seats_per_row + 1
        names = " | ".join(
            item.display_name for item in seated
        )
        rows.append(f"Row {number}: {names}")
    return rows
